{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "orin-dx-agent-plugins",
  "description": "Ten cooperating plugins covering the full development lifecycle — from requirement capture through spec, plan, implementation, verification, and shipping.",
  "owner": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "plugins": [
    {
      "name": "mason",
      "description": "Meta-plugin for scaffolding and auditing plugins, skills, and subagents. Generates plugin directory structure, validates conformance to ecosystem schemas, and designs shared schema contracts. Skills: scaffold-plugin, audit-plugin, design-schema, scaffold-subagent.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/mason",
        "ref": "main"
      }
    },
    {
      "name": "ranger",
      "description": "Cross-language bug hunting. Finds real bugs in live code through recon, hazard scanning, adversarial verification, and exit-gate verdict. Supersedes bug-hunter-rust and bug-hunter-ts.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/ranger",
        "ref": "main"
      }
    },
    {
      "name": "sentinel",
      "description": "Cross-cutting verification gate. Confirms that any stage artifact meets its criteria before the next stage begins. One skill, one recon-verify-judge pipeline, reused unchanged against any artifact type.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/sentinel",
        "ref": "main"
      }
    },
    {
      "name": "weaver",
      "description": "Need definition plugin. Captures and structures requirements before implementation begins. Integrates with GitHub Issues by default; extensible to Linear, Jira, or any issue tracker that produces the requirement@1 schema. Skills: capture-need, clarify-requirement, prioritize-backlog, connect-requirement, audit-backlog.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/weaver",
        "ref": "main"
      }
    },
    {
      "name": "vanguard",
      "description": "Research plugin. Investigates questions and requirements to build a documented evidence base before committing to a solution direction. Produces research-report@1.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/vanguard",
        "ref": "main"
      }
    },
    {
      "name": "scribe",
      "description": "Specification plugin. Turns requirements and research reports into unambiguous, testable specs. Detects spec drift against actual code. Skills: draft-spec, verify-spec, spec-drift, audit-spec, gate-spec, correct-spec, architect.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/scribe",
        "ref": "main"
      }
    },
    {
      "name": "muse",
      "description": "Component specification plugin. Turns UI/design intent into unambiguous, testable component specs — props, variants, per-state behavior, and accessibility criteria as testable propositions, gated before planning.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/muse",
        "ref": "main"
      }
    },
    {
      "name": "navigator",
      "description": "Planning plugin. Decomposes specs into sequenced, bite-sized implementation plans with TDD steps, exact code, and commit messages. No TBDs.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/navigator",
        "ref": "main"
      }
    },
    {
      "name": "smith",
      "description": "Implementation plugin. Executes plans via TDD cycle. Produces committed, tested code verified by the sentinel exit gate.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/smith",
        "ref": "main"
      }
    },
    {
      "name": "courier",
      "description": "Shipping plugin. Shepherds completed code through commit, PR creation, review response, and changeset documentation. Skills: commit, pr, changeset, receive-feedback, post-review, release.",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/orin-dx/agent-plugins.git",
        "path": "plugins/courier",
        "ref": "main"
      }
    }
  ]
}

